package dev.jackteng.encore;
import dev.jackteng.encore.catalog.*;
import dev.jackteng.encore.catalog.Models.*;
import dev.jackteng.encore.customer.CustomerService;
import dev.jackteng.encore.customer.CustomerService.Principal;
import dev.jackteng.encore.orders.*;
import dev.jackteng.encore.orders.OrderModels.*;
import dev.jackteng.encore.orders.OrderModels.Order;
import dev.jackteng.encore.orders.PaymentModels.*;
import dev.jackteng.encore.common.ApiErrors.Problem;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.test.web.servlet.MockMvc;
import jakarta.servlet.http.Cookie;
import com.fasterxml.jackson.databind.ObjectMapper;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"ticket.delivery.enabled=false","ticket.orders.enabled=true","ticket.mock-payments.enabled=true","ticket.admission.enabled=false","ticket.expiry.enabled=false"})
@AutoConfigureMockMvc
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class PaymentIntegrationTest {
 @Autowired OrderService orders;@Autowired PaymentService payments;@Autowired CatalogService catalog;@Autowired CustomerService customers;
 @Autowired JdbcTemplate db;@Autowired PlatformTransactionManager transactions;@Autowired MockMvc mvc;@Autowired ObjectMapper json;
 String manager="pay-manager-"+UUID.randomUUID();
 record Fixture(Principal customer,UUID ticket,Order order) {}
 @BeforeAll void seed(){assertEquals("ticket_demo",db.queryForObject("SELECT current_database()",String.class));db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),manager,"synthetic unused hash","MANAGER");}
 Principal customer(){var issue=customers.register("p-"+UUID.randomUUID().toString().substring(0,30),"合成付款",UUID.randomUUID().toString());return customers.authenticate(issue.token()).orElseThrow();}
 Fixture fixture(){return fixture(OffsetDateTime.now().plusHours(1));}
 Fixture fixture(OffsetDateTime end){var c=customer();var e=catalog.createEvent(manager,new EventInput(UUID.randomUUID(),0L,"pay-"+UUID.randomUUID(),"模擬付款合成活動","不收款","合成場地"));var s=catalog.createSession(manager,e.id(),new SessionInput(UUID.randomUUID(),0L,"合成場次",end.plusDays(1),OffsetDateTime.now().minusHours(1),end));var t=catalog.createTicket(manager,s.id(),new TicketInput(UUID.randomUUID(),0L,"一般票",1200,4,2));catalog.transition(manager,e.id(),new Transition(UUID.randomUUID(),1L),true);var o=orders.place(c,new Place(UUID.randomUUID(),t.id(),1,1,1200));return new Fixture(c,t.id(),o);}
 Pay pay(Fixture f,String scenario){return new Pay(UUID.randomUUID(),f.order().version(),f.order().totalTwd(),scenario);}
 Order start(Fixture f,String scenario){return payments.start(f.customer(),f.order().id(),pay(f,scenario));}
 Order reconcile(Fixture f,Order o){return payments.reconcile(f.customer(),o.id(),o.payment().id(),new Reconcile(UUID.randomUUID()));}
 void problem(int code,Runnable op){assertEquals(code,assertThrows(Problem.class,op::run).status);}
 int stock(Fixture f,String column){return db.queryForObject("SELECT "+column+" FROM ticket_type WHERE id=?",Integer.class,f.ticket());}
 int ledger(Fixture f){return db.queryForObject("SELECT count(*) FROM payment_inventory_event WHERE order_id=?",Integer.class,f.order().id());}
 void due(Fixture f){db.update("WITH stamp AS MATERIALIZED(SELECT clock_timestamp() clock) UPDATE ticket_order SET created_at=clock-interval '11 minutes',expires_at=clock-interval '1 minute' FROM stamp WHERE id=?",f.order().id());}
 @Test void durableInitiationAndSuccessConvertHeldToSold(){var f=fixture();var o=start(f,"SUCCESS");assertEquals(2,o.version());assertEquals("PENDING",o.payment().status());assertEquals(1,stock(f,"held"));assertEquals(0,stock(f,"sold"));o=reconcile(f,o);assertEquals("PAID",o.status());assertEquals("SUCCEEDED",o.payment().status());assertEquals(3,o.version());assertEquals(0,stock(f,"held"));assertEquals(1,stock(f,"sold"));assertEquals(1,ledger(f));assertFalse(orders.expire(o.id()));}
 @Test void originalInitAndReconcileReplayCurrentWithoutAnotherCharge(){var f=fixture();var b=pay(f,"SUCCESS");var o=payments.start(f.customer(),f.order().id(),b);var r=new Reconcile(UUID.randomUUID());var paid=payments.reconcile(f.customer(),o.id(),o.payment().id(),r);assertEquals(paid,payments.start(f.customer(),o.id(),b));assertEquals(paid,payments.reconcile(f.customer(),o.id(),o.payment().id(),r));assertEquals(1,ledger(f));assertEquals(1,db.queryForObject("SELECT count(*) FROM payment_attempt WHERE order_id=?",Integer.class,o.id()));}
 @Test void concurrentInitiationReplaysOneAttempt()throws Exception {var f=fixture();var body=pay(f,"SUCCESS");try(var pool=Executors.newFixedThreadPool(6)){var calls=new ArrayList<Callable<Order>>();for(int i=0;i<6;i++)calls.add(()->payments.start(f.customer(),f.order().id(),body));UUID id=null;for(var result:pool.invokeAll(calls)){var o=result.get();if(id==null)id=o.payment().id();assertEquals(id,o.payment().id());}}assertEquals(1,stock(f,"held"));}
 @Test void concurrentReconcileWithDifferentCommandsAppliesOneEvent()throws Exception {var f=fixture();var o=start(f,"SUCCESS");try(var pool=Executors.newFixedThreadPool(6)){var calls=new ArrayList<Callable<Order>>();for(int i=0;i<6;i++)calls.add(()->reconcile(f,o));for(var r:pool.invokeAll(calls))assertEquals("PAID",r.get().status());}assertEquals(1,ledger(f));assertEquals(1,stock(f,"sold"));}
 @Test void changedBodyAndCrossActionUUIDCannotReuseCommand(){var f=fixture();var body=pay(f,"SUCCESS");var o=payments.start(f.customer(),f.order().id(),body);problem(409,()->payments.start(f.customer(),o.id(),new Pay(body.requestId(),1,1200,"DECLINED")));problem(409,()->orders.cancel(f.customer(),o.id(),new Cancel(body.requestId(),2)));problem(409,()->payments.reconcile(f.customer(),o.id(),o.payment().id(),new Reconcile(body.requestId())));}
 @Test void staleQuoteAmountAndInvalidScenarioDoNotCreateAttempt(){var f=fixture();problem(409,()->payments.start(f.customer(),f.order().id(),new Pay(UUID.randomUUID(),1,1,"SUCCESS")));problem(409,()->payments.start(f.customer(),f.order().id(),new Pay(UUID.randomUUID(),2,1200,"SUCCESS")));problem(400,()->payments.start(f.customer(),f.order().id(),new Pay(UUID.randomUUID(),1,1200,"REAL")));assertNull(orders.detail(f.customer(),f.order().id()).payment());assertEquals(1,stock(f,"held"));}
 @Test void newRequestCannotCreateSecondAttempt(){var f=fixture();var o=start(f,"DECLINED");reconcile(f,o);var current=orders.detail(f.customer(),o.id());problem(409,()->payments.start(f.customer(),o.id(),new Pay(UUID.randomUUID(),current.version(),1200,"SUCCESS")));assertEquals(1,db.queryForObject("SELECT count(*) FROM payment_attempt WHERE order_id=?",Integer.class,o.id()));}
 @Test void declineDoesNotSellAndCanCancel(){var f=fixture();var o=reconcile(f,start(f,"DECLINED"));assertEquals("PENDING_PAYMENT",o.status());assertEquals("DECLINED",o.payment().status());assertEquals(1,stock(f,"held"));assertEquals("CANCELLED",orders.cancel(f.customer(),o.id(),new Cancel(UUID.randomUUID(),o.version())).status());assertEquals(0,stock(f,"sold"));}
 @Test void paidCountsTowardLimitAndCannotCancel(){var f=fixture();var o=reconcile(f,start(f,"SUCCESS"));problem(409,()->orders.cancel(f.customer(),o.id(),new Cancel(UUID.randomUUID(),o.version())));problem(409,()->orders.place(f.customer(),new Place(UUID.randomUUID(),f.ticket(),2,1,2400)));assertEquals(1,stock(f,"sold"));assertEquals(0,stock(f,"held"));}
 @Test void cancelledLateSuccessIsReviewAndNeverRevives(){var f=fixture();var o=start(f,"SUCCESS");orders.cancel(f.customer(),o.id(),new Cancel(UUID.randomUUID(),o.version()));var reviewed=reconcile(f,o);assertEquals("CANCELLED",reviewed.status());assertEquals("REVIEW",reviewed.payment().status());assertEquals("LATE_SUCCESS",reviewed.payment().reason());assertEquals(0,stock(f,"held"));assertEquals(0,stock(f,"sold"));assertEquals(0,ledger(f));}
 @Test void expiredWithoutSweeperIsReleasedInReconcile(){var f=fixture();var o=start(f,"SUCCESS");due(f);var reviewed=reconcile(f,o);assertEquals("EXPIRED",reviewed.status());assertEquals("REVIEW",reviewed.payment().status());assertEquals(0,stock(f,"held"));assertEquals(0,stock(f,"sold"));assertEquals(1,db.queryForObject("SELECT count(*) FROM order_inventory_event WHERE order_id=? AND phase='RELEASE'",Integer.class,o.id()));assertEquals(reviewed,reconcile(f,o));}
 @Test void workerExpiredThenLateSuccessReview(){var f=fixture();var o=start(f,"SUCCESS");due(f);assertTrue(orders.expire(o.id()));var reviewed=reconcile(f,o);assertEquals("EXPIRED",reviewed.status());assertEquals("REVIEW",reviewed.payment().status());assertEquals(0,stock(f,"sold"));}
 @Test void amountAndCurrencyMismatchGoReviewNotSold(){for(String field:List.of("amount=1","currency='USD'")){var f=fixture();var o=start(f,"SUCCESS");db.update("UPDATE mock_payment_receipt SET "+field+" WHERE attempt_id=?",o.payment().id());var reviewed=reconcile(f,o);assertEquals("AMOUNT_MISMATCH",reviewed.payment().reason());assertEquals("PENDING_PAYMENT",reviewed.status());assertEquals(1,stock(f,"held"));assertEquals(0,ledger(f));due(f);assertTrue(orders.expire(o.id()));}}
 @Test void extraSuccessHasReviewWithoutDoubleSelling(){var f=fixture();var o=reconcile(f,start(f,"SUCCESS"));db.update("INSERT INTO mock_payment_receipt VALUES(?,?, 'SUCCESS',1200,'TWD',clock_timestamp())",UUID.randomUUID(),o.payment().id());var reviewed=reconcile(f,o);assertEquals("PAID",reviewed.status());assertEquals("REVIEW",reviewed.payment().status());assertEquals("EXTRA_EVENT",reviewed.payment().reason());assertEquals(1,ledger(f));assertEquals(1,stock(f,"sold"));}
 @Test void alteredSameEventRejectedWithoutMutation(){var f=fixture();var o=reconcile(f,start(f,"SUCCESS"));db.update("UPDATE mock_payment_receipt SET amount=1 WHERE attempt_id=?",o.payment().id());problem(409,()->reconcile(f,o));assertEquals(o,orders.detail(f.customer(),o.id()));assertEquals(1,stock(f,"sold"));db.update("UPDATE mock_payment_receipt SET amount=1200 WHERE attempt_id=?",o.payment().id());}
 @Test void paymentAndCancellationRaceHasOneStockOutcome()throws Exception {var f=fixture();var o=start(f,"SUCCESS");try(var pool=Executors.newFixedThreadPool(2)){Callable<Object> cancel=()->{try{return orders.cancel(f.customer(),o.id(),new Cancel(UUID.randomUUID(),o.version()));}catch(Problem p){assertEquals(409,p.status);return null;}};for(var r:pool.invokeAll(List.of(cancel,()->reconcile(f,o))))r.get();}var current=orders.detail(f.customer(),o.id());assertTrue(List.of("PAID","CANCELLED").contains(current.status()));assertEquals(0,stock(f,"held"));assertEquals(current.status().equals("PAID")?1:0,stock(f,"sold"));}
 @Test void multipleExpiryWorkersAndPaymentReleaseOnce()throws Exception {var f=fixture();var o=start(f,"SUCCESS");due(f);try(var pool=Executors.newFixedThreadPool(4)){var calls=new ArrayList<Callable<Object>>();calls.add(()->reconcile(f,o));for(int i=0;i<3;i++)calls.add(()->orders.expire(o.id()));for(var r:pool.invokeAll(calls))r.get();}assertEquals("EXPIRED",orders.detail(f.customer(),o.id()).status());assertEquals("REVIEW",orders.detail(f.customer(),o.id()).payment().status());assertEquals(0,stock(f,"held"));assertEquals(0,stock(f,"sold"));assertEquals(1,db.queryForObject("SELECT count(*) FROM order_inventory_event WHERE order_id=? AND phase='RELEASE'",Integer.class,o.id()));}
 @Test void ownershipAndAttemptPathCannotCross(){var f=fixture();var o=start(f,"SUCCESS");var other=customer();problem(404,()->payments.start(other,o.id(),pay(f,"SUCCESS")));problem(404,()->payments.reconcile(other,o.id(),o.payment().id(),new Reconcile(UUID.randomUUID())));var b=fixture();problem(404,()->payments.reconcile(b.customer(),b.order().id(),o.payment().id(),new Reconcile(UUID.randomUUID())));}
 @Test void disabledFeatureReplaysAndReconcilesOldAttempt(){var f=fixture();var body=pay(f,"SUCCESS");var o=payments.start(f.customer(),f.order().id(),body);var off=new PaymentService(db,orders,false);var tx=new TransactionTemplate(transactions);assertEquals(o,tx.execute(s->off.start(f.customer(),o.id(),body)));assertEquals("PAID",tx.execute(s->off.reconcile(f.customer(),o.id(),o.payment().id(),new Reconcile(UUID.randomUUID()))).status());var other=fixture();problem(409,()->tx.execute(s->off.start(other.customer(),other.order().id(),pay(other,"SUCCESS"))));}
 @Test void disabledAndLoggedOutCannotPayOrReconcile(){var f=fixture();var o=start(f,"SUCCESS");db.update("UPDATE customer_account SET enabled=false WHERE id=?",f.customer().id());problem(401,()->reconcile(f,o));assertEquals(1,stock(f,"held"));due(f);assertTrue(orders.expire(o.id()));var b=fixture();db.update("DELETE FROM customer_session WHERE token_hash=?",b.customer().sessionHash());problem(401,()->start(b,"SUCCESS"));}
 @Test void paymentInventoryAuditFailureRollsBackAndOriginalRetryWorks(){var f=fixture();var o=start(f,"SUCCESS");var body=new Reconcile(UUID.randomUUID());db.execute("ALTER TABLE payment_inventory_event ADD CONSTRAINT m2c_fault CHECK(order_id<>'"+o.id()+"'::uuid) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->payments.reconcile(f.customer(),o.id(),o.payment().id(),body));assertEquals(o,orders.detail(f.customer(),o.id()));assertEquals(1,stock(f,"held"));assertEquals(0,stock(f,"sold"));assertEquals(0,db.queryForObject("SELECT count(*) FROM payment_event WHERE order_id=?",Integer.class,o.id()));}finally{db.execute("ALTER TABLE payment_inventory_event DROP CONSTRAINT m2c_fault");}assertEquals("PAID",payments.reconcile(f.customer(),o.id(),o.payment().id(),body).status());assertEquals(1,ledger(f));}
 @Test void eventAuditFailureRollsBackStockAndCommand(){var f=fixture();var o=start(f,"SUCCESS");var body=new Reconcile(UUID.randomUUID());db.execute("ALTER TABLE payment_event ADD CONSTRAINT m2c_event_fault CHECK(order_id<>'"+o.id()+"'::uuid) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->payments.reconcile(f.customer(),o.id(),o.payment().id(),body));assertEquals(1,stock(f,"held"));assertEquals(0,stock(f,"sold"));assertEquals(0,ledger(f));assertEquals(0,db.queryForObject("SELECT count(*) FROM order_command WHERE customer_id=? AND request_id=?",Integer.class,f.customer().id(),body.requestId()));}finally{db.execute("ALTER TABLE payment_event DROP CONSTRAINT m2c_event_fault");}assertEquals("PAID",payments.reconcile(f.customer(),o.id(),o.payment().id(),body).status());}
 @Test void initReceiptFailureRollsBackAndRetrySameUUID(){var f=fixture();var body=pay(f,"SUCCESS");db.execute("ALTER TABLE mock_payment_receipt ADD CONSTRAINT m2c_init_fault CHECK(amount<>1200) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->payments.start(f.customer(),f.order().id(),body));assertNull(orders.detail(f.customer(),f.order().id()).payment());assertEquals(1,orders.detail(f.customer(),f.order().id()).version());}finally{db.execute("ALTER TABLE mock_payment_receipt DROP CONSTRAINT m2c_init_fault");}assertNotNull(payments.start(f.customer(),f.order().id(),body).payment());}
 @Test void unknownResultLeavesAttemptAndOriginalCommandCanReconcile(){var f=fixture();var body=pay(f,"SUCCESS");var o=payments.start(f.customer(),f.order().id(),body);var receipt=db.queryForMap("SELECT * FROM mock_payment_receipt WHERE attempt_id=?",o.payment().id());db.update("DELETE FROM mock_payment_receipt WHERE attempt_id=?",o.payment().id());problem(409,()->reconcile(f,o));assertEquals(o,payments.start(f.customer(),o.id(),body));db.update("INSERT INTO mock_payment_receipt VALUES(?,?,?,?,?,?)",receipt.get("event_id"),receipt.get("attempt_id"),receipt.get("outcome"),receipt.get("amount"),receipt.get("currency"),receipt.get("created_at"));assertEquals("PAID",reconcile(f,o).status());}
 @Test void deadlineRecheckedAfterActualTicketLock()throws Exception {var f=fixture(OffsetDateTime.now().plusSeconds(4));var o=start(f,"SUCCESS");try(var pool=Executors.newSingleThreadExecutor()){new TransactionTemplate(transactions).execute(s->{db.queryForObject("SELECT id FROM ticket_type WHERE id=? FOR UPDATE",UUID.class,f.ticket());var task=pool.submit(()->reconcile(f,o));for(int i=0;i<60;i++){db.execute("SELECT pg_stat_clear_snapshot()");if(db.queryForObject("SELECT count(*) FROM pg_stat_activity WHERE wait_event_type='Lock' AND datname=current_database() AND query LIKE '%FOR UPDATE OF t%'",Integer.class)>0)break;try{Thread.sleep(30);}catch(Exception e){throw new AssertionError(e);}if(i==59)fail("Actual ticket lock wait required");}try{Thread.sleep(Math.max(1,Duration.between(OffsetDateTime.now(),o.expiresAt()).toMillis()+100));}catch(Exception e){throw new AssertionError(e);}s.setRollbackOnly();return task;}).get(4,TimeUnit.SECONDS);}assertEquals("REVIEW",orders.detail(f.customer(),o.id()).payment().status());assertEquals(0,stock(f,"sold"));assertEquals(0,stock(f,"held"));}
 @Test void httpCsrfIdentityAndSpoofedProviderEventDenied()throws Exception {var issued=customers.register("pw-"+UUID.randomUUID().toString().substring(0,30),"合成",UUID.randomUUID().toString());var c=new Cookie("TICKET_CUSTOMER_SESSION",issued.token());var f=fixture();String path="/api/customer/orders/"+f.order().id()+"/payments";mvc.perform(post(path).cookie(c).contentType("application/json").content(json.writeValueAsString(pay(f,"SUCCESS")))).andExpect(status().isForbidden());var csrf=mvc.perform(get("/api/customer/auth/csrf")).andReturn();var token=json.readTree(csrf.getResponse().getContentAsString());String body=json.writeValueAsString(pay(f,"SUCCESS"));body=body.substring(0,body.length()-1)+",\"providerEventId\":\"spoof\"}";mvc.perform(post(path).cookie(c,csrf.getResponse().getCookie("TICKET_CUSTOMER_CSRF")).header(token.get("headerName").asText(),token.get("token").asText()).contentType("application/json").content(body)).andExpect(status().isBadRequest());mvc.perform(get("/api/customer/orders/"+f.order().id())).andExpect(status().isUnauthorized());}
}
